<form class="shop-form" data-product data-tank-booking id="booking"><fieldset><legend>Tank capacity</legend><div class="chips"><?php foreach ($tanks as $i=>$p): ?><label><input type="radio" name="id" value="<?=(int)$p['id']?>" data-cost="<?=h($p['price'])?>" data-litres="<?=(int)$p['size_litres']?>" <?=$i===0?'checked':''?>><?=(int)$p['size_litres']?> L</label><?php endforeach; ?></div></fieldset>
<label>Adjust capacity<input type="range" id="capacity" min="0" max="<?=count($tanks)-1?>" value="0"></label><?php foreach ($tanks as $i=>$tank): if (!empty($tank['image'])): ?><img data-tank-photo="<?=(int)$tank['id']?>" src="<?=h($tank['image'])?>" alt="<?=h($tank['name'])?>" width="140" loading="lazy" <?=$i?'hidden':''?>><?php endif; endforeach; ?><div class="vessel"  aria-hidden="true"><div></div></div>
<label>Number of tanks<input type="number" name="qty" value="1" min="1" max="9999" required></label>
<label>Delivery date<input type="date" name="date" min="<?=date('Y-m-d')?>" required></label><label>Delivery slot<select name="slot"><?php foreach (CART_SLOTS as $s): ?><option><?=h($s)?></option><?php endforeach; ?></select></label><label>Delivery address<textarea name="address" required minlength="8" maxlength="500" autocomplete="street-address"></textarea></label><output></output><button class="primary">Add tank to cart</button></form>
